const siteId=location.pathname.split('/').pop();
let me=null,site=null,currentPage='home',currentDevice='desktop',editorDoc=null,selected=null,pendingOps=[],saveTimer=null,basicsTimer=null,basicSaving=false,mediaContext=null,brandAssetTarget=null,seoOgAssetId=null,footerLinks=[],activeDialog=null,dialogReturnFocus=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(url,opts={}){const headers={...(opts.headers||{})};if(opts.body&&!headers['Content-Type']&&!(opts.body instanceof FormData))headers['Content-Type']='application/json';if(opts.method&&opts.method!=='GET')headers['X-CSRF-Token']=sessionStorage.getItem('csrf')||me?.csrf_token||'';const r=await fetch(url,{...opts,headers});let j={};try{j=await r.json()}catch{}if(r.status===401){location.href='/login';throw new Error('Authentication required')}if(!r.ok){const d=j.detail;const err=new Error(typeof d==='string'?d:(d?.message||d?.code||'Request failed'));err.status=r.status;err.detail=d;throw err}return j}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1900)}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-media-tab]');if(b){e.preventDefault();showMediaTab(b.dataset.mediaTab)}});
function setSaveState(v){$('#saveState').textContent=v;$('#saveState').dataset.state=v.toLowerCase()}
