function fallbackInfo(el){const tag=el.tagName.toLowerCase();let fallback='';if(el.id&&!el.id.startsWith('zylora-'))fallback=`#${CSS.escape(el.id)}`;else{const cls=[...el.classList].filter(x=>!x.startsWith('zy-')).find(x=>/^[A-Za-z_][\w-]*$/.test(x));if(cls)fallback=`${tag}.${CSS.escape(cls)}`;else fallback=tag}const all=[...el.ownerDocument.querySelectorAll(tag)];return{fallback_selector:fallback,fallback_tag:tag,fallback_index:Math.max(0,all.indexOf(el)),target_id:el.dataset.zyloraId||'',target_kind:el.dataset.zyloraKind||tag,target_role:el.dataset.zyloraRole||''}}
function opBase(type,extra={}){if(!selected)throw new Error('Select an element first');const el=selected.el;return{page:currentPage,type,selector:selectorFor(selected.id),...fallbackInfo(el),...extra}}
function refreshHistoryButtons(){const h=editorDoc?.history||{};$('#undoBtn').disabled=!h.can_undo;$('#redoBtn').disabled=!h.can_redo}
