 if(el.tagName.toLowerCase()==='a'){content+=controlGroup('Link',`<label>Label<input id="iLinkLabel" value="${esc(el.textContent||'')}"></label><label>Destination<select id="iLinkType"><option value="page">Page</option><option value="url">External URL</option><option value="email">Email</option><option value="phone">Phone</option><option value="anchor">Anchor</option></select></label><label>Value<input id="iLinkHref" value="${esc(el.getAttribute('href')||'')}"></label><label class="check"><input id="iNewTab" type="checkbox" ${el.target==='_blank'?'checked':''}> Open in new tab</label><button class="primary" id="applyLink">Apply link</button><div class="button-row" id="pageLinkButtons">${pages().map(p=>`<button data-linkpage="${esc(p)}">${esc(pageLabel(p))}</button>`).join('')}</div>`)}
 if(kind==='field'){content+=controlGroup('Form field',`<label>Placeholder<input id="iPlaceholder" value="${esc(el.getAttribute('placeholder')||'')}"></label><label class="check"><input id="iRequired" type="checkbox" ${el.hasAttribute('required')?'checked':''}> Required</label><button id="applyField">Apply field settings</button><p class="msg">The field remains connected to Zylora lead capture.</p>`)}
