 if(kind==='section'){content+=controlGroup('Section',`<div class="button-row"><button id="moveUp">Move up</button><button id="moveDown">Move down</button><button id="hideSection">Hide</button>${editability==='EDITABLE'?'<button id="duplicateSection">Duplicate</button>':''}<button id="resetSection">Reset</button></div>`)}
