async function loadA11y(){const j=await api(`/api/sites/${siteId}/accessibility-check?page=${encodeURIComponent(currentPage)}`);$('#a11yList').innerHTML=j.warnings.length?j.warnings.map(w=>`<article class="revision-item"><b>${esc(w.type.replaceAll('_',' '))}</b><p>${esc(w.message)}</p>${w.target?`<button data-focus-node="${esc(w.target)}">Select element</button>`:''}</article>`).join(''):'<div class="revision-item"><b>No detected accessibility warnings</b><p class="msg">Automated checks are helpful but do not replace human review.</p></div>';$$('[data-focus-node]').forEach(b=>b.onclick=()=>{closeDrawers();const el=$('#previewFrame').contentDocument?.querySelector(selectorFor(b.dataset.focusNode));if(el){selectElement(el);el.scrollIntoView({behavior:'smooth',block:'center'})}})}
function recoveryKey(){return `zylora:editor-recovery:${siteId}`}
function saveLocalRecovery(){try{localStorage.setItem(recoveryKey(),JSON.stringify({tagline:$('#tagline').value,description:$('#description').value,accent:$('#accentText').value,saved_at:Date.now()}))}catch{}}
function scheduleBasicsSave(){saveLocalRecovery();setSaveState('Unsaved');clearTimeout(basicsTimer);basicsTimer=setTimeout(()=>{basicsTimer=null;saveBasics(true)},1200)}
function restoreLocalRecovery(){try{const raw=localStorage.getItem(recoveryKey());if(!raw)return;const r=JSON.parse(raw),server=Date.parse(site?.updated_at||'')||0;if(Number(r.saved_at||0)<=server){localStorage.removeItem(recoveryKey());return}if(typeof r.tagline==='string')$('#tagline').value=r.tagline;if(typeof r.description==='string')$('#description').value=r.description;if(/^#[0-9a-f]{6}$/i.test(r.accent||'')){ $('#accentText').value=r.accent;$('#accent').value=r.accent }$('#saveMsg').textContent='Recovered unsaved browser changes. Autosaving…';scheduleBasicsSave()}catch{}}
async function saveBasics(quiet=false){if(basicSaving)return;basicSaving=true;clearTimeout(basicsTimer);basicsTimer=null;try{setSaveState('Saving…');await api(`/api/sites/${siteId}`,{method:'PUT',body:JSON.stringify({tagline:$('#tagline').value,description:$('#description').value,accent:$('#accentText').value})});try{localStorage.removeItem(recoveryKey())}catch{}setSaveState('Saved');$('#saveMsg').textContent=site?.status==='LIVE'?'Saved to draft. Republish when ready.':'Saved automatically.';await loadDocument({keepSelection:true});await reloadPreview();if(!quiet)toast('Draft changes saved')}catch(e){setSaveState('Unsaved');$('#saveMsg').textContent=e.message}finally{basicSaving=false}}
async function aiApply(){const ins=$('#aiInstruction').value.trim();if(ins.length<3){$('#aiMsg').textContent='Describe the change first.';return}try{if($('#aiSitewide')?.checked){$('#aiMsg').textContent='Planning a validated site-wide change…';const preview=await api(`/api/sites/${siteId}/ai-edit/sitewide`,{method:'POST',body:JSON.stringify({instruction:ins,expected_version:editorDoc?.document_version,preview_only:true})});const impact=preview.impact||{};if(!(impact.operations||0)){ $('#aiMsg').textContent='No safe site-wide edits were proposed.';return }const ok=confirm(`Apply ${impact.operations} validated changes across ${(impact.pages||[]).length} page(s)? This will use ${preview.credit_cost_on_apply} AI credits and creates a recovery point first.`);if(!ok){$('#aiMsg').textContent='Site-wide preview cancelled.';return}$('#aiMsg').textContent='Applying site-wide edit atomically…';const j=await api(`/api/sites/${siteId}/ai-edit/sitewide`,{method:'POST',body:JSON.stringify({instruction:ins,expected_version:preview.document_version,preview_only:false,preview_id:preview.preview_id})});$('#aiMsg').textContent=`Applied ${j.impact?.operations||0} validated actions across ${j.impact?.pages?.length||0} pages.`;await loadDocument();await reloadPreview();toast('Site-wide AI edit applied');return}$('#aiMsg').textContent='Planning and validating structured edits…';const j=await api(`/api/sites/${siteId}/ai-edit`,{method:'POST',body:JSON.stringify({instruction:ins,page:currentPage})});$('#tagline').value=j.tagline;$('#description').value=j.description;if(j.message){$('#aiMsg').textContent=j.message;return}$('#aiMsg').textContent=`Applied ${j.operations?.length||0} validated action${j.operations?.length===1?'':'s'} with ${j.provider}.`;await loadDocument();await reloadPreview();toast('AI edit applied to draft')}catch(e){$('#aiMsg').textContent=e.message}}
async function publish(){await flushOps();return ZyloraPublishFlow.start(siteId,{onPublished:j=>{site.status='LIVE';$('#siteStatus').textContent='LIVE';$('#publishBtn').textContent='Republish';toast(j.structural_reset_applied?'Published Free · layout reset, text & images preserved':'Published snapshot updated');window.open(j.url,'_blank','noopener')},onError:e=>toast(e.message)})}
async function unlockSourceExport(){try{await flushOps();const r=await fetch(`/api/sites/${siteId}/export`);if(r.ok){location.href=`/api/sites/${siteId}/export`;return}if(r.status!==402){toast('Export unavailable');return}const cfg=await api('/api/source-export/config'),usd=cfg.prices?.USD??9900;if(!confirm(`Source export is separate from free ownership transfer. Unlock this site's Next.js source for $${(usd/100).toFixed(0)}?`))return;const o=await api(`/api/sites/${siteId}/source-export/order`,{method:'POST',body:JSON.stringify({currency:'USD'})});if(o.entitled){location.href=`/api/sites/${siteId}/export`;return}if(o.provider==='mock'){await api(`/api/sites/${siteId}/source-export/verify`,{method:'POST',body:JSON.stringify({order_id:o.order_id,payment_id:o.mock_payment_id,signature:o.mock_signature})});location.href=`/api/sites/${siteId}/export`;return}if(!window.Razorpay){const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';await new Promise((ok,bad)=>{s.onload=ok;s.onerror=bad;document.head.appendChild(s)})}new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,order_id:o.order_id,name:'Zylora',description:'Next.js source export',handler:async p=>{await api(`/api/sites/${siteId}/source-export/verify`,{method:'POST',body:JSON.stringify({order_id:p.razorpay_order_id,payment_id:p.razorpay_payment_id,signature:p.razorpay_signature})});location.href=`/api/sites/${siteId}/export`}}).open()}catch(e){toast(e.message)}}
