async function init(){me=await api('/api/auth/me');sessionStorage.setItem('csrf',me.csrf_token);site=await api(`/api/sites/${siteId}`);$('#siteName').textContent=site.business_name;$('#siteStatus').textContent=site.status;$('#tagline').value=site.tagline;$('#description').value=site.description;$('#accent').value=site.accent;$('#accentText').value=site.accent;$('#publishBtn').textContent=site.status==='LIVE'?'Republish':'Publish';restoreLocalRecovery();await loadDocument();renderPages();fillBrand();const aiPrompt=new URLSearchParams(location.search).get('ai');if(aiPrompt){$('#aiInstruction').value=aiPrompt;switchLeftPanel('aiPanel')}
 $('#previewFrame').addEventListener('load',()=>{injectCanvasTools();if(selected){const el=$('#previewFrame').contentDocument?.querySelector(selectorFor(selected.id));if(el)selectElement(el)}});await reloadPreview();$('#saveBtn').onclick=()=>saveBasics(false);$('#aiApply').onclick=aiApply;$('#aiSitewide').onchange=e=>{$('#aiPage').disabled=e.target.checked};$('#publishBtn').onclick=publish;if(new URLSearchParams(location.search).get('resumePublish')==='1'){history.replaceState({},'',location.pathname);setTimeout(()=>publish(),0)};$('#previewBtn').onclick=()=>window.open(previewUrl().split('?')[0],'_blank','noopener');$('#refreshPreview').onclick=reloadPreview;$('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#exportBtn').onclick=e=>{e.preventDefault();unlockSourceExport()};$('#accent').oninput=e=>{$('#accentText').value=e.target.value;scheduleBasicsSave()};$('#accentText').oninput=e=>{if(/^#[0-9a-f]{6}$/i.test(e.target.value))$('#accent').value=e.target.value;scheduleBasicsSave()};$('#tagline').oninput=scheduleBasicsSave;$('#description').oninput=scheduleBasicsSave;
 $$('[data-width]').forEach(b=>b.onclick=()=>{$$('[data-width]').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentDevice=b.dataset.device;$('#previewFrame').style.width=b.dataset.width});$$('.left-tabs [data-panel]').forEach(b=>b.onclick=()=>switchLeftPanel(b.dataset.panel));$$('[data-inspector]').forEach(b=>b.onclick=()=>switchInspector(b.dataset.inspector));$$('[data-open]').forEach(b=>b.onclick=()=>{if(b.dataset.open==='brandPanel')fillBrand();openDrawer(b.dataset.open)});$$('[data-close]').forEach(b=>b.onclick=closeDrawers);$('#a11yBtn').onclick=()=>openDrawer('a11yPanel');$('#applyBrand').onclick=applyBrand;$('#saveBusinessProfile').onclick=saveBusinessProfile;$('#createBackup').onclick=createBackup;$('#brandLogoBtn').onclick=()=>openMedia({type:'brand',field:'logo_asset_id'});$('#brandAltLogoBtn').onclick=()=>openMedia({type:'brand',field:'alternate_logo_asset_id'});$('#brandFaviconBtn').onclick=()=>openMedia({type:'brand',field:'favicon_asset_id'});$('#applySeo').onclick=applySeo;$('#saveSiteSeo').onclick=saveSiteSeo;$('#footerLinkAdd').onclick=addFooterLink;$('#seoHealthBtn').onclick=runSeoHealth;$('#seoAiAssist').onclick=seoAiAssist;$('#seoOgImage').onclick=()=>openMedia({type:'seo'});$('#closeMedia').onclick=closeMedia;$$('[data-media-tab]').forEach(b=>b.onclick=()=>showMediaTab(b.dataset.mediaTab));$('#uploadBtn').onclick=uploadAndUse;$('#stockSearch').onclick=stockSearch;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMedia();closeDrawers();return}if(e.key==='Tab'&&activeDialog){const f=focusables(activeDialog);if(f.length){const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!activeDialog){e.preventDefault();if(e.shiftKey)redo();else undo()}});window.addEventListener('beforeunload',e=>{if(pendingOps.length||basicSaving||basicsTimer||$('#saveState').textContent==='Saving…'){e.preventDefault();e.returnValue=''}})}
init().catch(e=>{console.error(e);toast(e.message||'Editor failed to load')});
